/* Nelson Textbook data chunk 02/07; generated only from absi/Nelson.zip. */
window.__SHB_NELSON_QUESTIONS__=(window.__SHB_NELSON_QUESTIONS__||[]).concat([{"id":"NEL-DERMATOLOG-042","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The cardinal feature of atopic dermatitis is","o":["skin rash","lichenification","fibrotic papules","intense pruritus","dry skin"],"k":3,"ex":"Intense pruritus, worse at night, is the cardinal feature; the rash results from scratching.","more":"Nelson explanation:\n42.(D). Intense pruritus, especially at night, and cutaneous reactivity are the cardinal\nfeatures of atopic dermatitis.\n\nOptions:\nA rash and B–C are consequences of itch; E dry skin is the hallmark per Q40.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Overlaps Q40 (same options reversed)","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 213 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":42,"f":true},{"id":"NEL-DERMATOLOG-045","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Older children with chronic atopic dermatitis have lichenification and a tendency to be localized to","o":["flexural folds of the extremities","forehead","scalp","diaper area","cheeks"],"k":0,"ex":"Older children have lichenified plaques in flexural folds (infants: face and extensors).","more":"Nelson explanation:\n45.(A).\n\nOptions:\nB–E are infantile or seborrhoeic sites.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 214 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":45,"f":false},{"id":"NEL-DERMATOLOG-046","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The following are the major clinical features of atopic dermatitis (AD) EXCEPT","o":["pruritus","family history","Crelapsing dermatitis","facial eczema in infants","extensor eczema in adolescents"],"k":4,"ex":"Major features: pruritus, typical distribution, relapsing course, personal/family atopy. Adolescents have flexural, not extensor, eczema.","more":"Nelson explanation:\n46.(E). The major clinical features in atopic dermatitis are (pruritus, facial and extenso)\neczema in infants and children, flexural eczema in adolescents, relapsing dermatitis and\npersonal or family history).\n\nOptions:\nE is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 214 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":46,"f":false},{"id":"NEL-DERMATOLOG-049","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"The first line therapy of atopic dermatitis (AD) is","o":["moisturizers","cyclosporine","antihistamine","tar preparations","topical corticosteroids"],"k":0,"ex":"Emollients/moisturisers repair the dry skin barrier and are first-line; topical steroids are for flares.","more":"Nelson explanation:\n49.(A). Because patients with AD have impaired skin barrier function from reduced lipid\nlevels, they present with diffuse, abnormally dry skin, or xerosis. Moisturizers are first-\nline therapy.\n\nOptions:\nB cyclosporine is last-line; C antihistamines only help sleep; D tar is old; E steroids are second step.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 215 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":49,"f":false},{"id":"NEL-DERMATOLOG-050","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Prevention of atopic dermatitis in infancy includes the following measures ExCEPT","o":["breast feeding","feeding with a hypoallergenic hydrolyzed formula","use of probiotics","elimination of implicated food allergen from the mother diet","use of special type napkins"],"k":4,"ex":"Breastfeeding, hydrolysed formula, probiotics and maternal allergen avoidance are prevention measures; special napkins are irrelevant.","more":"Nelson explanation:\n50.(E).\n\nOptions:\nE is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 215 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":50,"f":false},{"id":"NEL-DERMATOLOG-051","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Which of the following vitamin deficiencies often accompanies severe atopic dermatitis?","o":["E","C","A","D","B12"],"k":3,"ex":"Vitamin D deficiency often accompanies severe AD; vitamin D supports barrier and antimicrobial function.","more":"Nelson explanation:\n51.(D). Vitamin D deficiency often accompanies severe AD. Vitamin D enhances skin\nbarrier function, reduces corticosteroid requirements to control inflammation and\naugments skin antimicrobial function.\n\nOptions:\nOnly D is linked by Nelson.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 215 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":51,"f":false},{"id":"NEL-DERMATOLOG-052","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Clinical Case","q":"Predictive factors of a poor prognosis for atopic dermatitis includes all the following EXCEPT","o":["widespread atopic dermatitis in childhood","filaggrin gene null mutations","concomitant allergic rhinitis and asthma","family history of atopic dermatitis in parents or siblings","late age at onset of atopic dermatitis"],"k":4,"ex":"Widespread disease, filaggrin mutations, associated asthma/rhinitis and family history predict persistence; early (not late) onset is poor.","more":"Nelson explanation:\n52.(E).\n\nOptions:\nE is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 215 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":52,"f":false},{"id":"NEL-DERMATOLOG-053","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The best choice of antibiotic in treating localized impetiginous lesions in patients with atopic dermatitis is","o":["oral erythromycin","oral cephalexin","topical mupirocin","topical ampicillin","topical gentamycin"],"k":2,"ex":"Localized impetiginised eczema is treated with topical mupirocin; systemic antibiotics are for widespread infection.","more":"Nelson explanation:\n53.(C). Erythromycin and azithromycin are usually beneficial for patients who are not\ncolonized with a resistant S. aureus strain; a first-generation cephalosporin (cephalexin)\nis recommended for macrolide-resistant S. aureus. Topical mupirocin is useful in the\ntreatment of localized impetiginous lesions, with systemic antibiotics for widespread\ninfections.\n\nOptions:\nA/B oral drugs for widespread disease; D/E topical ampicillin/gentamicin are not used.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 215 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":53,"f":false},{"id":"NEL-DERMATOLOG-054","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"IgE anti-bodies against Malassezia furfur have been found in patients with atopic dermatitis of 205 [Continuation on source page 216]","o":["head and neck","hands and arms","legs and feet","upper chest","lower abdomen"],"k":0,"ex":"Malassezia is a lipophilic yeast of seborrhoeic areas, so IgE to it is linked to head-and-neck AD.","more":"Nelson explanation:\n54.(A). There has been particular interest in the role of Malassezia furfur in atopic\ndermatitis because it is lipophilic yeast commonly present in the seborrheic areas of\nthe skin.\n\nOptions:\nOnly A (head and neck) matches the yeast's habitat.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ OCR: page marker inside the stem","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 215 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":54,"f":true},{"id":"NEL-DERMATOLOG-055","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"One of the following statements is TRUE regarding skin tests in identifying food allergies in patients with atopic dermatitis","o":["negative skin and blood test results for allergen-specific ige have a low predictive value for excluding suspected allergens positive results of skin or blood tests using foods often correlate with clinical symptoms and no need to be confirmed with controlled food challenges","extensive elimination diets are commonly required","even with multiple majority of patients react to more than 3 foods","potential allergens can be identified by a careful history and performing selective skin prick tests or in vitro blood testing for allergen- specific IgE"],"k":null,"ex":"Food allergens are identified by history plus selected skin-prick or specific IgE tests; tests alone do not prove allergy.","more":"Nelson explanation:\n55.(E). For the other stems; A- high predictive value, B- Positive skin test often do not\ncorrelate with clinical symptoms, C- Rarely required, and D- The majority react to less\nthan 3 foods.\n\nOptions:\nA negative tests have HIGH predictive value; B positive tests often do not match symptoms; C extensive diets rarely needed; D most react to <3 foods.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"The OCR question text/options or source key are incomplete; the answer is disabled until checked.","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 216 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":55,"f":true,"kx":true},{"id":"NEL-DERMATOLOG-056","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"One of the following medications used in treatment of atopic dermatitis should be discontinued after failure to achieve good results within 4-6 weeks","o":["methotrexate","azathioprine","cyclosporine","mycophenolate mofetil","omalizumab"],"k":3,"ex":"Systemic immunosuppressants are stopped when there is no response; mycophenolate is stopped after 4–6 weeks without benefit.","more":"Nelson explanation:\n56.(D).\n220\n[Source page 231]\n\nOptions:\nOther agents need longer trials.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Detail from Nelson only; explanation line is OCR page marker","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 216 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":56,"f":true},{"id":"NEL-DERMATOLOG-057","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Systemic corticosteroids are rarely indicated in the treatment of atopic dermatitis because","o":["toxic side effects after long term use","rebound flare after therapy discontinuation","cannot do more than what topical can","tapering is required even after short term use","antimetabolites can do better in modifying disease course"],"k":1,"ex":"Oral steroids give fast improvement but severe rebound flare on stopping, so they are rarely used.","more":"Nelson explanation:\n57.(B). The dramatic clinical improvement that may occur with systemic corticosteroids\nis frequently associated with a severe rebound flare of atopic dermatitis after therapy\ndiscontinuation.\n\nOptions:\nA also true but not the main reason; C/D/E are incorrect statements.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ A is also partly defensible; Nelson key B","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 216 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":57,"f":true},{"id":"NEL-DERMATOLOG-061","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Exfoliative dermatitis may develop in patients with atopic dermatitis and extensive skin involvement, usually caused by inappropriate therapy or superinfection with","o":["E. coli","Herpes zoster","− Herpes simplex","Streptococcal pyogen","Trichophyton rubrum"],"k":2,"ex":"Erythroderma follows superinfection (S. aureus toxin or herpes simplex) or steroid withdrawal; herpes causes eczema herpeticum.","more":"Nelson explanation:\n61.(C). Exfoliative dermatitis associated with generalized redness, scaling, weeping,\ncrusting, systemic toxicity, lymphadenopathy, and fever, and is usually caused by\nsuperinfection (e.g., with toxin-producing S. aureus or HSV infection) or inappropriate\ntherapy. In some cases, the withdrawal of systemic glucocorticoids used to control\nsevere AD precipitates exfoliative erythroderma.\n\nOptions:\nAmong options only herpes simplex is listed by Nelson; A, B, D, E are not typical.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 217 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":61,"f":false},{"id":"NEL-DERMATOLOG-063","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Systemic allergic responses to insects are attributed to IgE antibody response caused primarily by","o":["ticks","spiders","hymenoptera","scorpions","triatoma (kissing bug)"],"k":2,"ex":"Hymenoptera (bee, wasp, ant) venom causes IgE-mediated systemic reactions.","more":"Nelson explanation:\n63.(C).\n\nOptions:\nTicks, spiders, scorpions and kissing bugs rarely cause IgE anaphylaxis.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 217 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":63,"f":false},{"id":"NEL-DERMATOLOG-066","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"The MOsT reliable diagnostic modality for detection of venom-specific IgE is","o":["in vitro serum assay for venom-specific IgE","skin test","serum tryptase level","plasma histamine","radioallergosorbent assay"],"k":1,"ex":"Skin testing is the most reliable test for venom-specific IgE.","more":"Nelson explanation:\n66.(B).\n\nOptions:\nA serum assay is second-line; C–D are not diagnostic; E is an old assay.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 218 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":66,"f":false},{"id":"NEL-DERMATOLOG-067","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"In the presence of convincing history of a severe systemic reaction, the next diagnostic step for those with initially negative skin test is","o":["in vitro serum assay for venom-specific IgE","repeat skin test after 4-6 weeks","serum tryptase level","plasma histamine","basophil histamine release test"],"k":0,"ex":"If the skin test is negative but the history is convincing, serum venom-specific IgE is the next step.","more":"Nelson explanation:\n67.(A). In vitro serum assay for venom-specific IgE is recommended if skin test results\nare negative in the presence of a convincing history of a severe systemic reaction.\n\nOptions:\nB repeating is the second step after A; C–E are not diagnostic.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 218 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":67,"f":false},{"id":"NEL-DERMATOLOG-069","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Anaphylactic reactions after a Hymenoptera sting are treated exactly like anaphylaxis from any cause. Of the following, the drug of choice is","o":["oxygen","epinephrine","antihistamines","corticosteroids","intravenous fluids"],"k":1,"ex":"Adrenaline (epinephrine) IM is the first drug in any anaphylaxis; other drugs are adjuncts.","more":"Nelson explanation:\n69.(B). Adjunctive treatment includes antihistamines, corticosteroids, intravenous\nfluids, oxygen, and transport to the emergency room.\n\nOptions:\nA,C,D,E are supportive only.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 218 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":69,"f":false},{"id":"NEL-DERMATOLOG-070","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A TRUE indication of venom immunotherapy in a six-year-old boy is","o":["large local reaction with positive skin test and positive in vitro test 208 [Continuation on source page 219]","generalized cutaneous reaction with positive skin test and negative in vitro test","generalized cutaneous reaction with positive in vitro test and negative skin test","systemic reaction with positive skin test and negative in vitro test","systemic reaction with negative skin test and negative in vitro test"],"k":3,"ex":"Any systemic reaction with a positive skin or serum test is an indication; large local or only cutaneous reactions in children are not.","more":"Nelson explanation:\n70.(D). Systemic reaction at any age with positive skin test / in vitro test is an indication\nfor venom immunotherapy. Large local reaction and generalized cutaneous reactions in\nchildren are not indications for both diagnostic tests (skin and in vitro tests) and venom\nimmunotherapy.\n\nOptions:\nA,B,C are local/cutaneous reactions; D is systemic with a positive test; E has both tests negative.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 218 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":70,"f":false},{"id":"NEL-DERMATOLOG-071","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Skeeter syndrome is a large local reaction to stinging and biting insects. Of the following, the TRUE statement is","o":["Ig E mediated response","usually occurs in older children","usually followed by anaphylaxis","mosquito is the responsible agent","misdiagnosed as erythema nodosum"],"k":3,"ex":"Skeeter syndrome is a large local reaction to mosquito bites in young children, often mistaken for cellulitis, without anaphylaxis.","more":"Nelson explanation:\n71.(D). Skeeter syndrome is a large local reaction to mosquito bite, it happens usually\nin young children and misdiagnosed as cellulitis. This is not an Ig E mediated reaction\nbut because of the vasoactive and irritant material from the mosquito, it does not\ncause anaphylaxis.\n\nOptions:\nA: Nelson says non-IgE (some sources say IgE); B older children is wrong; C never anaphylaxis; E mimics cellulitis.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Key D safe; option A is debated in the literature","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 219 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":71,"f":true},{"id":"NEL-DERMATOLOG-072","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The eye is a common target of allergic disorders because of its marked vascularity and direct contact with allergens in the environment. Of the following, the MOsT immunologically active tissue of the external eye is","o":["iris","sclera","eyelids","eyelashes","conjunctiva"],"k":4,"ex":"The conjunctiva is the immunologically active tissue of the external eye (mast cells).","more":"Nelson explanation:\n72.(E).\n\nOptions:\nOther eye parts have fewer mast cells.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 219 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":72,"f":false},{"id":"NEL-DERMATOLOG-073","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The MOsT common hypersensitivity response of the eye is","o":["allergic conjunctivitis","vernal keratoconjunctivitis","atopic keratoconjunctivitis","giant papillary conjunctivitis","contact allergy"],"k":0,"ex":"Allergic conjunctivitis is the commonest ocular hypersensitivity (≈25% of people).","more":"Nelson explanation:\n73.(A). Allergic conjunctivitis is the most common hypersensitivity response of the eye,\naffecting approximately 25% of the general population and 30% of children with atopy.\n\nOptions:\nB–E are rarer and more severe forms.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 219 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":73,"f":false},{"id":"NEL-DERMATOLOG-074","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The MOsT sight-threatening type of ocular allergy is","o":["contact allergy","vernal keratoconjunctivitis","giant papillary conjunctivitis","seasonal allergic conjunctivitis","perennial allergic conjunctivitis"],"k":1,"ex":"Vernal and atopic keratoconjunctivitis threaten sight because of corneal involvement.","more":"Nelson explanation:\n74.(B). Vernal keratoconjunctivitis and atopic keratoconjunctivitis are sight-threatening\nentities and causes visual morbidity and suspected cases need to be referred to an\nophthalmologist.\n\nOptions:\nOther types are mild.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 219 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":74,"f":false},{"id":"NEL-DERMATOLOG-075","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The MosT common presenting complain of allergic conjunctivitis is","o":["pain","itching","redness",".blurred vision","purulent discharge 209 [Continuation on source page 220]"],"k":1,"ex":"Itching, with tearing, is the main symptom; pain and loss of vision suggest another cause.","more":"Nelson explanation:\n75.(B). Patients with allergic conjunctivitis complain of variable ocular itching, rather\nthan pain, with increased tearing.\n221\n[Source page 232]\n\nOptions:\nA/D are red flags; C/E suggest infection.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 219 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":75,"f":false},{"id":"NEL-DERMATOLOG-076","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Topical ophthalmic medications usually cause","o":["contact allergy","allergic conjunctivitis","vernal keratoconjunctivitis","atopic keratoconjunctivitis","giant papillary conjunctivitis"],"k":0,"ex":"Topical eye drops and contact-lens solutions commonly cause contact allergy of the eyelids.","more":"Nelson explanation:\n76.(A). Contact allergy typically involves the eyelids but can also involve the\nconjunctivae. It is being recognized more frequently in association with increased\nexposure to topical medications, contact lens solutions, and preservatives.\n\nOptions:\nB–E are IgE or atopic forms not tied to drops.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 220 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":76,"f":false},{"id":"NEL-DERMATOLOG-079","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Non IgE mediated urticaria can be caused by","o":["milk","hymenoptera {","Epstein-barr virus","Jatex","blood"],"k":2,"ex":"Non-IgE urticaria is caused by direct mast-cell stimulation (viruses such as EBV, radio-contrast, opiates, NSAIDs).","more":"Nelson explanation:\n79.(C). Acute urticaria can also result from non~lgE-mediated stimulation of mast cells,\ncaused by radiocontrast agents, viral agents (including hepatitis 8 and Epstein-Barr\nvirus), opiates, and nonsteroidal anti-inflammatory agents.\n\nOptions:\nA, B, D, E (milk, stings, latex, blood) are IgE-mediated.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 220 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":79,"f":false},{"id":"NEL-DERMATOLOG-080","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Chronic urticaria may be caused by","o":["latex","peanut","IV immunoglobulin","streptococcal pharyngitis","systemic lupus erythematosus"],"k":4,"ex":"Chronic urticaria is linked to autoimmune diseases (SLE, thyroid, IBD, celiac).","more":"Nelson explanation:\n80.(E). Autoimmune disease, like SLE, Juvenile rheumatoid arthritis, thyroid disease,\ninflammatory bowel diseases and celiac disease, are well established causes of chronic\nurticaria.\n\nOptions:\nA–D are triggers of acute IgE urticaria.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 220 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":80,"f":false},{"id":"NEL-DERMATOLOG-081","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"The drug of choice for cold-induced urticaria is","o":["loratadine","epinephrine IM","cyproheptadine","diphenhydramine","oral corticosteroid 210 [Continuation on source page 221]"],"k":2,"ex":"Cold-induced urticaria responds best to cyproheptadine.","more":"Nelson explanation:\n81.(C).\n\nOptions:\nA–B–D–E are less effective or only for acute episodes.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 220 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":81,"f":false},{"id":"NEL-DERMATOLOG-082","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Acute urticaria is a self-limited illness requiring little treatment. All the following can be uSed EXCEPT","o":["loratadine","hydroxyzine","epinephrine IM","H2 antihistamines","oral corticosteroid"],"k":3,"ex":"Acute urticaria needs little treatment: antihistamines, steroid short course, IM adrenaline if angioedema; H2 blockers are used in chronic disease.","more":"Nelson explanation:\n82.(D). H2 antihistamines used in chronic urticaria.\n\nOptions:\nD is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 221 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":82,"f":false},{"id":"NEL-DERMATOLOG-083","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Skin biopsy for diagnosis of possible urticarial vasculitis is recommended for","o":["urticarial lesions that persist at different locations for >24 hr","those with non- pigmented or non-purpuric components","those that burn more than itch","those with associated collagen vascular diseases","those appeared after peanuts ingestion"],"k":3,"ex":"Biopsy is advised when wheals last >24 h in the same place, are purpuric/pigmented or burn.","more":"Nelson explanation:\n83.(D). Skin biopsy is recommended for urticarial lesions that persist at the same\nlocation for >24 hr, those with pigmented or purpuric components, and those that burn\nmore than itch. Collagen vascular diseases such as systemic lupus may manifest\nurticarial vasculitis as a presenting feature.\n\nOptions:\nA (different locations) and B,C,E do not meet criteria; D is accepted only because collagen diseases can present this way.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Key D weakly supported; stem A is a deliberate negation","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 221 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":83,"f":true},{"id":"NEL-DERMATOLOG-084","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The differential diagnosis of chronic urticaria includes the following ExCEPT","o":["cutaneous mastocytosis","systemic mastocytosis","complement- mediated mast cell degranulation in malignancies","cutaneous blistering disorders","dermatographism"],"k":4,"ex":"Dermatographism is itself a physical urticaria, so it is not a differential diagnosis.","more":"Nelson explanation:\n84.(E).\n\nOptions:\nA–D are real differentials.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 221 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":84,"f":false},{"id":"NEL-DERMATOLOG-085","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The MosT common childhood symptoms of hereditary angioedema is","o":["cutaneous non-pitting but pruritic edema associated with urticaria","cutaneous pitting but non-pruritic edema not associated with urticaria","cutaneous pitting and pruritic edema associated with urticaria","cutaneous non-pitting and non-pruritic edema associated with urticaria","cutaneous non-pitting and non-pruritic edema not associated with urticaria"],"k":4,"ex":"HAE gives non-pitting, non-pruritic swelling without urticaria.","more":"Nelson explanation:\n85.(E).\n86.(8). Vaccination is a trigger, not a cofactor in anaphylaxis, others are cofactors.\n\nOptions:\nA,C,D carry pruritus/urticaria (allergic angioedema); B is pitting.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ OCR: Nelson explanation block mixes in Q86 text","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 221 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":85,"f":true},{"id":"NEL-DERMATOLOG-087","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"One of the principal pathologic features in fatal anaphylaxis is","o":["acute bronchial obstruction","hypotension","behavioral change","abdominal pain","vomiting 211 [Continuation on source page 222]"],"k":0,"ex":"Fatal anaphylaxis is mainly acute bronchial obstruction with hyperinflation and laryngeal oedema.","more":"Nelson explanation:\n87.(A). Principal pathologic features in fatal anaphylaxis include acute bronchial\nobstruction with pulmonary hyperinflation, pulmonary edema, intraalveolar\nhemorrhaging, visceral congestion, laryngeal edema, and urticaria and angioedema.\nAcute hypotension is attributed to vasomotor dilation and/or cardiac dysrhythmias.\n\nOptions:\nB hypotension is also important but is a secondary effect.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 221 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":87,"f":false},{"id":"NEL-DERMATOLOG-088","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Sudden collapse in the presence of cutaneous symptoms in a previously healthy child should raise suspicion of","o":["vasovagal collapse","anaphylaxis","aspiration","pulmonary embolism","seizure disorder"],"k":1,"ex":"Sudden collapse with skin signs (urticaria) should suggest anaphylaxis; the other causes lack skin findings.","more":"Nelson explanation:\n88.(B). Other choices are to be considered in cases where there are no cutaneous\nmanifestations.\n\nOptions:\nA,C,D,E can collapse without skin changes.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 222 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":88,"f":false},{"id":"NEL-DERMATOLOG-089","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Cutaneous symptoms may be absent in anaphylaxis in","o":["5%","10%","20%","30%","40%"],"k":2,"ex":"Skin signs are usually present but about 20% of anaphylaxis cases have no skin symptoms, so absence of rash does not exclude it.","more":"Nelson explanation:\n89.(C).\n\nOptions:\nNumeric recall; only C (20%) per Nelson.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 222 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":89,"f":false},{"id":"NEL-DERMATOLOG-090","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"The best diagnostic test for anaphylaxis in a child exposed to an allergen 3 hours before arrival to hospital is","o":["plasma histamine","skin test","radioallergosorbent assay","plasma tryptase","immunoCAP IgE test"],"k":3,"ex":"Tryptase stays raised for hours, so it is the best lab test when the child arrives 3 h after exposure; histamine is short-lived.","more":"Nelson explanation:\n90.(D). Plasma histamine is elevated for a brief period but is unstable and difficult to\nmeasure in a clinical setting. Plasma tryptase is more stable and remains elevated for\nseveral hours but often is not elevated, especially in food-induced anaphylactic\nreactions.\n91.(8). Patients may experience biphasic anaphylaxis, which occurs when anaphylactic\nsymptoms recur after apparent resolution. More than 90% of biphasic responses occur\nwithin 4 hours, so patients should be observed for at least 4 hr before being discharged\nfrom the emergency department.\n\nOptions:\nA histamine peaks and falls in minutes; B/C/E identify the allergen, not the acute event.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ OCR: Nelson explanation block runs into Q91 text","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 222 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":90,"f":true},{"id":"NEL-DERMATOLOG-096","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"Skin biopsy is not usually necessary for confirming the diagnosis of serum sickness because","o":["the complement C and Ca yield better results","the clinical examination is enough for the diagnosis","skin test is superior to biopsy","the histopathological findings are not specific","it may be complicated by local infection"],"k":3,"ex":"Serum sickness is diagnosed clinically; skin biopsy shows non-specific changes.","more":"Nelson explanation:\n96.(D). Not specific and not diagnostic.\n222\n[Source page 233]\n\nOptions:\nA,C,E are not the reason; B is true but incomplete.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 223 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":96,"f":false},{"id":"NEL-DERMATOLOG-098","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"All the following are symptoms of acute IgE mediated food allergy ExCEPT","o":["urticaria","pruritis","abdominal pain","diarrhea","wheezing"],"k":1,"ex":"IgE food reactions cause urticaria, itching, wheeze and GI symptoms within minutes to 2 h.","more":"Nelson explanation:\n98.(B).\n\nOptions:\nAll five listed items occur in IgE food allergy, so the stem 'EXCEPT' is not satisfied by B.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Key B (pruritus) looks wrong or option text corrupted → Needs Review","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 223 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":98,"f":true},{"id":"NEL-DERMATOLOG-099","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"One of the following presentations is a non-IgE mediated food allergy 213 [Continuation on source page 224]","o":["Heiner syndrome","gastrointestinal anaphylaxis","rhino conjunctivitis","oral allergy syndrome","angioedema"],"k":0,"ex":"Heiner syndrome (milk-induced pulmonary haemosiderosis) is a non-IgE food reaction; the other options are IgE-mediated.","more":"Nelson explanation:\n99.(A). Heiner syndrome (food induced pulmonary hemosiderosis) is a non-lgE\nmediated food allergy.\n\nOptions:\nB,C,D,E are classic IgE presentations.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 223 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":99,"f":false},{"id":"NEL-DERMATOLOG-100","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The onset of presentation of food allergy is late in","o":["hen's egg white",". peanuts","shellfish","soybean","cow's milk"],"k":2,"ex":"Shellfish allergy typically starts in adulthood; egg, milk, soy and peanut start in childhood.","more":"Nelson explanation:\n100.(C). The onset is usually during adulthood. Others are earlier in presentation.\n\nOptions:\nA,B,D,E appear early.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 224 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":100,"f":false},{"id":"NEL-DERMATOLOG-101","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Food protein-induced enterocolitis syndrome Is characterized by allthe following EXCEPT","o":["manifests in the first months of life","vomiting occurs 1-3 hours after feeding","hypotension occurs in approximately 15% of cases","commonly improved with ingestion of soy protein based formula","usually resolve by the age of three years of life"],"k":3,"ex":"FPIES (non-IgE) presents in early infancy with delayed vomiting after milk/soy, may cause shock, and usually resolves by 3 years.","more":"Nelson explanation:\n101.(D). Commonly provoked by ingestion of milk and soy based protein formula.\n\nOptions:\nD is false: soy formula can also trigger FPIES, so it does not improve it.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 224 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":101,"f":false},{"id":"NEL-DERMATOLOG-102","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The MOsT common cause of food protein induced enteropathy is","o":["peanuts",". fish","cow's milk","eggs","tree nuts"],"k":2,"ex":"Cow's milk protein is the commonest cause of food-protein enteropathy.","more":"Nelson explanation:\n102.(C).\n\nOptions:\nOther foods are less frequent triggers.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 224 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":102,"f":false},{"id":"NEL-DERMATOLOG-103","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The MosT severe form of food protein-induced enteropathy is","o":["celiac disease","eosinophilic esophagitis","oral allergy syndrome","acute gastrointestinal allergy","food protein proctocolitis reactions?"],"k":0,"ex":"Coeliac disease is the most severe, permanent food-protein enteropathy (gluten).","more":"Nelson explanation:\n103.(A).\n\nOptions:\nB–E are milder or limited forms.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 224 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":103,"f":false},{"id":"NEL-DERMATOLOG-104","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Wheezing occurs in approximately which percent of IgE-mediated food allergic","o":["15%",". 25%","35%","45%","55% 214 [Continuation on source page 225]"],"k":1,"ex":"Respiratory signs are less common than skin signs: wheeze in about a quarter of IgE food reactions.","more":"Nelson explanation:\n104.(B).\n\nOptions:\nNumeric recall; key B (25%).","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 224 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":104,"f":false},{"id":"NEL-DERMATOLOG-105","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Administration of the following vaccine is contraindicated in children with eg8 allergy","o":["MMR","Influenza","DPT","yellow fever","rabies"],"k":3,"ex":"Yellow fever vaccine is grown in eggs, so egg allergy is a contraindication; MMR and influenza are generally safe.","more":"Nelson explanation:\n105.(D).\n\nOptions:\nA,B,C,E contain little or no egg protein.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 225 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":105,"f":false},{"id":"NEL-DERMATOLOG-106","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"The only way to establish the diagnosis of cell-mediated food reactions is","o":["breath hydrogen test","endoscopy","elimination and challenge test","IgE testing","skin test"],"k":2,"ex":"No lab test identifies cell-mediated food reactions; elimination then challenge confirms the diagnosis.","more":"Nelson explanation:\n106.(C). There are no laboratory studies to help identify foods responsible for cell-\nmediated reactions. Consequently, elimination diets followed by food challenges are\nthe only way to establish the diagnosis.\n\nOptions:\nA,B,D,E detect other conditions or IgE only.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 225 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":106,"f":false},{"id":"NEL-DERMATOLOG-107","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Unpredictable drug reactions include","o":["dose dependent","drug toxicity","drug interactions x","adverse effects","allergic reaction"],"k":4,"ex":"Predictable reactions depend on dose, toxicity or interactions; allergic (and idiosyncratic) reactions are unpredictable.","more":"Nelson explanation:\n107.(E).\n\nOptions:\nA–D are predictable; E is the unpredictable type.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Allergic Disorders · question page 225 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":107,"f":false},{"id":"NEL-DERMATOLOG-001","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Which of the following malignant tumors is least likely to occur in adults in comparison with children?","o":["acute Lymphoblastic Leukemia (ALL)","osteosarcoma","medulloblastoma","retinoblastoma","Hodgkin lymphoma"],"k":3,"ex":"Embryonal tumours such as retinoblastoma occur almost only in childhood; ALL, osteosarcoma, medulloblastoma and Hodgkin also occur in adults.","more":"Nelson explanation:\n1.(D). Retinoblastoma is an embryonal tumor, usually occurs in childhood.\n\nOptions:\nA–C,E have adult cases.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 378 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":1,"f":false},{"id":"NEL-DERMATOLOG-002-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A 9-year-old boy develops acute myelogenous leukemia (AML) one year after completion of therapy for soft tissue sarcoma at his right thigh. Which of the following chemotherapeutic agents is MosT likely the cause of secondary acute myelogenous leukemia AML in this boy?","o":["cyclophosphamide","vincristine","etoposide","doxorubicin","cisplatin"],"k":2,"ex":"Secondary AML after etoposide (epipodophyllotoxin) appears early (<2 y); alkylators come later (3–5 y).","more":"Nelson explanation:\n2.(C). Epipodophyllotoxins like etoposide may cause secondary AMl early within two\nyears after administration; alkylating agents like cyclophosphamide may cause\nsecondary AMl as far as 5 years after therapy.\n\nOptions:\nA cyclophosphamide is late; B,E are not leukaemogenic; D anthracycline can also cause it.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Doxorubicin also leukaemogenic; key per Nelson · ⚠ advanced/specialised for course level","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 378 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":2,"f":true},{"id":"NEL-DERMATOLOG-004","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Constellation of aniridia and hemihypertrophy is strongly associated with increased risk of which of the following tumors?","o":["rhabdomyosarcoma","hepatoblastoma","Wilms'tumor","neuroblastoma","medulloblastoma"],"k":2,"ex":"Aniridia (WAGR) and hemihypertrophy are linked to Wilms tumour.","more":"Nelson explanation:\n4.(C). Beckwith-Wiedemann syndrome, an overgrowth syndrome characterized by\nmacrosomia, macroglossia, hemihypertrophy, omphalocele, and renal anomalies, is\nassociated with an increased risk of Wilms' tumor, hepatoblastoma,\nrhabdomyosarcoma, neuroblastoma, and adrenal cortical carcinoma, while aniridia is\nassociated with Wilms' tumor.\n\nOptions:\nA,B,D,E are linked to other syndromes.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 378 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":4,"f":false},{"id":"NEL-DERMATOLOG-005","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Clinical Case","q":"During the routine exam of an infant, the parents state a strong family history of adenomatous polyposis. 368 [Continuation on source page 379] The statement that should be included during the discussion is","o":["the infant is at increased risk for colonic adenocarcinoma","the infant is at increased risk of acute lymphocytic leukemia","the infant is at increased risk of intestinal Burkitt lymphoma","the infant is at increased risk of hepatoblastoma","the infant is at increased risk of germ cell tumor"],"k":3,"ex":"Familial adenomatous polyposis and Beckwith–Wiedemann increase risk of hepatoblastoma in infants.","more":"Nelson explanation:\n5.(D). Beckwith-Wiedemann syndrome, hemihypertrophy, Gardner syndrome, and\nfamily history of adenomatous polyposis are associated with increased risk of\nhepatoblastoma.\n\nOptions:\nA colonic cancer comes in adulthood; B,C,E are unrelated.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 378 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":5,"f":false},{"id":"NEL-DERMATOLOG-006","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Undescended testis is a risk factor for the development of which of the following tumors?","o":["rhabdomyosarcoma","leukemia","yolk sac tumor","lymphoma","neuroblastoma"],"k":2,"ex":"Undescended testis predisposes to testicular germ-cell tumours (yolk sac, seminoma).","more":"Nelson explanation:\n6.(C).\n\nOptions:\nA,B,D,E are not linked.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 379 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":6,"f":false},{"id":"NEL-DERMATOLOG-007","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Epstein-Barr virus (EBV) infection is more likely to be associated with all the following malignancies EXCEPT","o":["Burkitt lymphoma","nasopharyngeal carcinoma","T-cell lymphoma","Hodgkin lymphoma","hepatocellular carcinoma"],"k":4,"ex":"EBV links to Burkitt, nasopharyngeal carcinoma, Hodgkin and T-cell lymphoma; HCC comes from HBV/HCV.","more":"Nelson explanation:\n7.(E). Hepatocellular carcinoma is associated with hepatitis B and C infection.\n\nOptions:\nE is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 379 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":7,"f":false},{"id":"NEL-DERMATOLOG-008","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Clinical Case","q":"Which of the following malignancies is least likely to occur in a 10-month-old infant?","o":["neuroblastoma","nephroblastoma","retinoblastoma","hepatoblastoma","Ewing sarcoma"],"k":4,"ex":"Embryonal tumours dominate the first year; bone sarcomas appear later.","more":"Nelson explanation:\n8.(E). During the 1st yr of life, embryonal tumors such as neuroblastoma,\nnephroblastoma (Wilms tumor), retinoblastoma, rhabdomyosarcoma, hepatoblastoma,\nand medulloblastoma are most common. As children age, bone malignancies, Hodgkin\ndisease, gonadal germ cell malignancies (testicular and ovarian carcinomas), and other\ncarcinomas increase in incidence.\n\nOptions:\nA–D are embryonal tumours.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 379 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":8,"f":false},{"id":"NEL-DERMATOLOG-009","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Hepatitis C virus infection is a risk factor for which of the following malignancy?","o":["hepatoblastoma","splenic lymphoma","Hodgkin lymphoma","nasopharyngeal carcinoma","cervical carcinoma"],"k":1,"ex":"HCV is a risk for HCC and splenic lymphoma; HCC is not offered here.","more":"Nelson explanation:\n9.(B). Hepatitis C virus infection is a risk factor for hepatocellular carcinoma and is also\nassociated with splenic lymphoma.\n\nOptions:\nA,C,D,E are linked to other agents.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Low-yield; key per Nelson","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 379 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":9,"f":true},{"id":"NEL-DERMATOLOG-011","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Which of the following chromosomal abnormalities in acute lymphoblastic leukemia of childhood carry a favorable outcome?","o":["t(12;21)","t(4;11)","t(9;22)","hypodiploidy","11q23"],"k":0,"ex":"t(12;21) and hyperdiploidy are favourable; t(9;22), t(4;11) and hypodiploidy are poor.","more":"Nelson explanation:\n11.(A).\n\nOptions:\nB–E are adverse.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 380 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":11,"f":false},{"id":"NEL-DERMATOLOG-012","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"You are meeting with parents of 10-year-old child who recently develops acute lymphoblastic leukemia (ALL); the mother has a concern about risk of CNS relapse. Which of the following is LEAsT likely to increase the risk of CNS relapse in children with ALL?","o":["first traumatic lumbar puncture (LP)","T-cell leukemia","cranial nerve involvement at the time of diagnosis","presence of lymphoblast in the CSF at any time during treatment","age of more than 10 year at the time of the diagnosis"],"k":4,"ex":"CNS relapse risk rises with T-cell disease, CNS findings and traumatic LP.","more":"Nelson explanation:\n12.(E).\n\nOptions:\nA–D increase risk; E (age >10) is said not to.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Age ≥10 is usually adverse; explanation missing → Needs Review · ⚠ advanced/specialised for course level","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 380 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":12,"f":true},{"id":"NEL-DERMATOLOG-018-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Granulocytic sarcoma masses are commonly seen in which type of the following malignancies?","o":["neuroblastoma","rhabdomyosarcoma","soft tissue sarcoma","ALL","AML"],"k":4,"ex":"Granulocytic sarcoma (chloroma) is a solid mass of myeloid blasts typical of AML.","more":"Nelson explanation:\n18.(E).\n\nOptions:\nA–D do not form chloromas.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 381 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":18,"f":false},{"id":"NEL-DERMATOLOG-020-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"You are explaining the risk of leukemia in children with Down syndrome to medical students; your discussion will include all the following statements ExcEpT","o":["acute leukemia occurs more frequently in children with Down syndrome than in the general population 371 [Continuation on source page 382]","AML is more common in children with Down syndrome in the 1\" 3 yr of life than ALL as compared with the ratio of ALL/AML in general population","in children with Down syndrome who have AML, the expected outcome of treatment is slightly inferior to that for other children","patients with Down syndrome who develops acute leukemia demonstrate a remarkable sensitivity to antimetabolites","neonates with Down syndrome may develop a transient leukemia or myeloproliferative disorder"],"k":2,"ex":"Down syndrome raises leukaemia risk; AML-M7 is commoner early; AML in DS responds better (>80% survival).","more":"Nelson explanation:\n20.(C). In AML, patients with Down syndrome have much better outcomes than non-\nDown syndrome children, with a >80% long-term survival rate.\n\nOptions:\nOption C (inferior outcome) is the false statement.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 381 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":20,"f":false},{"id":"NEL-DERMATOLOG-021-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A healthy 20-day-old male neonate with Down syndrome appears pale; examination reveals a palpable liver 6 cm below the right costal margin and palpable spleen 3 cm below the left costal margin; lab findings include: hemoglobin, 8.8 g/dl; platelets count, 55000/mm3; white blood cell count, 18700/mm3 with 10% blast cells; bone marrow examination is consistent with acute leukemia. Of the following, the BEST approach for the management is","o":["intensive chemotherapy","low dose chemotherapy","pulses of chemotherapy","bone marrow transplantation","close follow up"],"k":4,"ex":"Neonates with Down syndrome may have transient leukaemia that resolves, so observation (not chemotherapy) is used.","more":"Nelson explanation:\n21.(E). Approximately 10% of neonates with Down syndrome develop a transient\nleukemia or myeloproliferative disorder which usually resolves within the 1st 3 mo of\nlife. Although these neonates can require temporary transfusion support, they do not\nrequire chemotherapy unless there is evidence of life-threatening complications.\nHowever, those patients require close follow-up, because 20-30% will develop typical\nleukemia by 3 yr of life.\n\nOptions:\nA–D are overtreatment.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 382 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":21,"f":false},{"id":"NEL-DERMATOLOG-022","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Clinical Case","q":"Which of the following types of leukemia is MosT likely to develop in a 2-year-old child with Down syndrome who has been developed transient myeloproliferative disorder in the neonatal period?","o":["ALL","CML","AML MI","AML M6","AML M7"],"k":4,"ex":"20–30% of transient disease progress to AML-M7 by 3 years.","more":"Nelson explanation:\n22.(E). Twenty-thirty percent of patients who have Down syndrome and who develop\ntransient leukemia or myeloproliferative disorder will develop typical leukemia (often\nacute megakaryocytic leukemia) by 3 yr of life (mean onset, 16 mo).\n\nOptions:\nA–D are less likely.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 382 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":22,"f":false},{"id":"NEL-DERMATOLOG-024-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Hodgkin lymphoma in children usually has favorable outcome; howevn, the prognosis may be grim in some cases. Poor prognostic factors in Hodgkin Lymphoma Include all the following Except","o":["age of more than 15 year at the time of the diagnosls 372 [Continuation on source page 383]","stage IV disease","presence of \"B\" symptoms","poor response to therapy manifested by positron emission tomography (PET) scan positivity","presence of bulky mediastinal mass"],"k":0,"ex":"Adverse factors: stage IV, B symptoms, bulky mediastinum, poor early PET response.","more":"Nelson explanation:\n24.(A).\n\nOptions:\nAge >15 is not listed as a standard poor factor.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Explanation missing · ⚠ advanced/specialised for course level","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 382 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":24,"f":true},{"id":"NEL-DERMATOLOG-025","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Clinical Case","q":"A 12-year-old male adolescent, recently diagnosed with Hodgkin lymphoma; the PET-CT scan shows an involvement of the left cervical and supraclavicular lymph nodes; he has a history of drenching night sweating and high grade fever. Based on Ann Arbor Staging Classification for Hodgkin Lymphoma, the patient is classified as","o":["stage IA","stage IB","stage IIA","stage 118","stage IIIB"],"k":3,"ex":"Two lymph-node regions on one side of the diaphragm = stage II; B symptoms (night sweats, fever) add 'B'.","more":"Nelson explanation:\n25.(D). Stage il includes involvement of 2 or more lymph node regions on the same side\nof the diaphragm (Il) or localized involvement of an extralymphatic organ or site and 1\nor more lymph node regions on the same side of the diaphragm (ilE). HL is subclassified\ninto A or B categories: A is used to identify asymptomatic patients and B is for patients\nwho exhibit any B symptoms.\n\nOptions:\nIA/IB single region; IIA lacks B symptoms; IIIB crosses diaphragm.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 383 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":25,"f":false},{"id":"NEL-DERMATOLOG-026","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Which of the following manifestations is more specific to occur in anaplastic large cell lymphoma (ALCL) than other types of non-Hodgkin Lymphoma (NHL)?","o":["primary intestinal involvement","bone marrow involvement","CNS involvement","primary cutaneous involvement","primary mediastinal involvement"],"k":3,"ex":"ALCL often involves the skin, unlike lymphoblastic (mediastinal/BM/CNS) or Burkitt (abdomen/jaw).","more":"Nelson explanation:\n26.(D). The primary site of tumor involvement and metastasis pattern varies by\npathologic subtype. Lymphoblastic lymphoma (LBL) commonly manifests as an\nintrathoracic or mediastinal supradiaphragmatic mass and also has a predilection for\n386\n[Source page 397]\nspreading to the bone marrow and CNS. Burkitt lymphoma (BL) commonly manifests as\nabdominal (sporadic type) or head and neck (endemic type) tumor and can metastasize\nto the bone marrow or CNS. Diffuse large B-cell lymphoma (DLBcL) commonly\nmanifests as either an abdominal or mediastinal primary and, rarely, disseminates to\nthe bone marrow or CNS. ALCL manifests either as a primary cutaneous manifestation\n(10%) or as systemic disease (90%) with dissemination to liver, spleen, lung, or\nmediastinum. Bone marrow or CNS disease is rare in ALCL.\n\nOptions:\nA,B,C,E are typical of other subtypes.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 383 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":26,"f":false},{"id":"NEL-DERMATOLOG-027","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Tumor lysis syndrome (TLS) is a common complication during the treatment of pediatric malignancies, which of the following malignancies is more likely to manifest such complication?","o":["acute myelogenous leukemia AML","nephroblastoma","neuroblastoma","Burkitt lymphoma","Rhabdomyosarcoma"],"k":3,"ex":"TLS is commonest in rapidly dividing tumours such as Burkitt lymphoma and leukaemia.","more":"Nelson explanation:\n27.(D). TLS can occur from rapid cell turnover, which is especially common in Burkitt\nlymphoma.\n\nOptions:\nA can cause it but less than Burkitt; B,C,E rarely.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 383 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":27,"f":false},{"id":"NEL-DERMATOLOG-029-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A 5-year-old child, recently diagnosed with ileocecal Burkitt lymphoma; lab investigations reveal: serum uric acid 12 mg/dl, serum sodium, 145 meq/dl; serum potassium, 4.5 meg/dl; serum phosphate 4.4 meq/dl; serum calcium, 8.9 mg/dl; blood urea, 22 mg/dl; serum creatinine, 0.8 mg/dl. Of the following, the MOsT effective treatment is","o":["excessive hydration","sodium bicarbonate",". xanthine oxidase inhibitor","recombinant urate oxidase","no treatment"],"k":3,"ex":"High uric acid in Burkitt lymphoma is treated with recombinant urate oxidase (rasburicase) plus hydration.","more":"Nelson explanation:\n29.(D). Recombinant urate oxidase is preferred in patients with a high risk of tumor\nlysis. Frequently, only a single dose is needed; however, repeat doses can be given if a\nsubsequent rise in uric acid is seen.\n\nOptions:\nA,B are supportive; C allopurinol prevents new uric acid only; E wrong.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 384 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":29,"f":false},{"id":"NEL-DERMATOLOG-036","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Extraneural metastasis from primary brain tumors is less likely to occur. Which of the following primary brain tumor is MosT commonly metastasizing extraneurally?","o":["meduiloblastoma","primitive neuroectodermal tumor (PNET)","ependymoma","malignant glioma","choroid plexus carcinoma"],"k":0,"ex":"Medulloblastoma most often seeds outside the CNS.","more":"Nelson explanation:\n36.(A).\n\nOptions:\nB–E spread less.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 385 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":36,"f":false},{"id":"NEL-DERMATOLOG-037","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Childhood primary brain tumors are less likely to metastasize extraneurally. Which of the following is MOsT likely considered a risk factor for extraneural metastasis?","o":["supratentorial tumor","age of the patient of less than 10 year","female gender","ventriculoperitoneal (VP) shunt insertion","glial tumors 375 [Continuation on source page 386]"],"k":3,"ex":"A ventriculoperitoneal shunt can carry tumour cells to the peritoneum.","more":"Nelson explanation:\n37.(D). Ventriculoperitoneal shunts have been known to allow extraneural metastases,\nprimarily within the peritoneal cavity but also systemically.\n\nOptions:\nA,B,C,E are not risk factors.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 385 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":37,"f":false},{"id":"NEL-DERMATOLOG-038-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Small round blue cell tumors refer to tumors that have round blue cells histologically. They include all the following EXCEPT","o":["neuroblastoma","non-Hodgkin lymphoma","osteosarcoma","Ewing sarcoma","rhabdomyosarcoma"],"k":2,"ex":"Neuroblastoma, NHL, Ewing and rhabdomyosarcoma are small round blue cell tumours; osteosarcoma is not.","more":"Nelson explanation:\n38.(C).\n\nOptions:\nC is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 386 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":38,"f":false},{"id":"NEL-DERMATOLOG-039-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Clinical Case","q":"A 9-mo-old infant develops a left adrenal mass; histological examination reveals a significant degree of undifferentiated round blue cells consistent with neuroblastoma. Which of the following genetic characteristics of the tumor cells carry a better outcome?","o":["amplification of the MYCN (N-myc) proto-oncogene","hyperdiploidy","loss of heterozygosity of 1p chromosome","loss of heterozygosity of 11q chromosome","gain of 17q chromosome"],"k":1,"ex":"MYCN amplification and 1p/11q loss are poor; hyperdiploidy in infants is favourable.","more":"Nelson explanation:\n39.(B). Hyperdiploidy confers better prognosis if the child is younger than 1 yr of age at\ndiagnosis. Amplification of MyCN is strongly associated with advanced tumor stage and\npoor outcomes. Other chromosomal abnormalities, including loss of heterozygosity of\n1p, 11q, and 14q, and gain of 17q, are commonly found in neuroblastoma tumors and\nare also associated with worse outcomes.\n\nOptions:\nA,C,D,E are adverse.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 386 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":39,"f":false},{"id":"NEL-DERMATOLOG-040-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"A 1-year-old child develops right eye ptosis, myosis, and loss of sweating; you suspect neuroblastoma. Of the following, the MosT valuable investigation to confirm the diagnosis is","o":["Computerized tomography (CT) scan of the neck and chest","CT scan of the abdomen","CT scan of the brain","magnetic resonance imaging (MRl) of the brain","X-ray the chest"],"k":0,"ex":"Horner syndrome (ptosis, miosis, anhidrosis) points to a cervical/thoracic sympathetic tumour, so CT neck/chest.","more":"Nelson explanation:\n40.(A). Horner syndrome, characterized by unilateral ptosis, myosis, and anhidrosis, is\nassociated with a thoracic or cervical primary tumor (e.g., superior cervical ganglion).\nSymptoms do not resolve with tumor resection.\n387\n[Source page 398]\n\nOptions:\nB abdomen is the usual site but not with Horner; C,D,E are less suitable.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 386 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":40,"f":false},{"id":"NEL-DERMATOLOG-043","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Investigation","q":"You are evaluating a 6-mo-old girl with a firm abdominal mass. Radiography reveals a calcified small right suprarenal mass. The tumor is completely resected and histologically is confirmed as neuroblastoma. Metastatic work-up shows massive liver involvement, 10% bone marrow involvement by tumor cells, and multiple subcutaneous nodules involvement. There is no bony involvement. The N-myc oncogene from the tumor is not amplified. According to the international neuroblastoma staging system, the infant is stratified as","o":["stagel","stage II A","stage III","stage IV","E stage IVS"],"k":4,"ex":"Infant <1 y with small primary, liver, skin and limited marrow involvement but no bone = stage 4S.","more":"Nelson explanation:\n43.(E). Infants younger than 1 yr of age also can present in unique fashion, termed\nstage 4S, with widespread subcutaneous tumor nodules, massive liver involvement,\nlimited bone marrow disease, and a small primary tumor without bone involvement or\nother metastases.\n\nOptions:\nA–D do not allow such metastases.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 387 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":43,"f":false},{"id":"NEL-DERMATOLOG-044","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A 10-mo-old boy has a left suprarenal mass. Surgery is accomplished with complete surgical removal of the mass as well as the non-adherent ipsilateral lymph nodes; multiple contralateral lymph nodes biopsies are taken during surgery. The histology reveals poorly differentiated neuroblastoma with microscopic involvement of the ipsilateral lymph nodes; the contralateral lymph nodes are negative for tumor cells. Of the following, the BEsT therapeutic approach for this infant is","o":["chemotherapy","radiotherapy","concomitant chemo-radiotherapy","chemotherapy followed by radiotherapy","close observation"],"k":4,"ex":"Low-risk (stage 2A) neuroblastoma needs surgery alone.","more":"Nelson explanation:\n44.(E). The infant has stage 2A and is stratified as low risk. The usual treatment for\nchildren with low-risk neuroblastoma is surgery for stages 1 and 2 and observation for\nstage 4S with cure rates generally >90% without further therapy.\n\nOptions:\nA–D are overtreatment.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 387 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":44,"f":false},{"id":"NEL-DERMATOLOG-045-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Children with high-risk neuroblastoma have poor survival. Current treatment consists of all the following ExCEPT","o":["surgery","intensive chemotherapy","radiation","allogenic bone marrow transplantation","differentiating agents (13-cis-retinoic acid)"],"k":3,"ex":"High-risk NB: surgery, chemo, radiation, autologous stem-cell rescue and retinoic acid; allogeneic BMT is not standard.","more":"Nelson explanation:\n45.(D). High-dose chemotherapy with autologous stem cell rescue, and not allogenic\nbone marrow transplantation, is one of the treatment modality for high risk patients.\n\nOptions:\nD is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 387 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":45,"f":false},{"id":"NEL-DERMATOLOG-048","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"A 2-year-old child is being evaluated for a right flank mass; radiological appearance is consistent with right renal Wilms' tumor. During radical nephrectomy there is intra- abdominal tumor rupture stated by the surgeon. Of the following, the BEsT therapeutic approach for this child is","o":["chemotherapy","radiotherapy","concomitant chemotherapy-radiotherapy","another surgery","observation"],"k":2,"ex":"Spillage at surgery raises the stage and adds radiotherapy to chemotherapy.","more":"Nelson explanation:\n48.(C). The child is stratified as stage II; so he needs chemo-radiotherapy.\n\nOptions:\nA–B alone insufficient; D,E wrong.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ Stage assignment (II vs III) differs by protocol · ⚠ advanced/specialised for course level","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 388 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":48,"f":true},{"id":"NEL-DERMATOLOG-049-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"Although children with Wilms' tumor have a favorable prognosis, there are some adverse factors that affect outcome. All the following are poor prognostic factors in children with Wilms' tumor ExCEPT","o":["young age at diagnosis","advanced stage","large tumors","anaplastic histology","loss of heterozygosity at chromosome 1p and 16q"],"k":0,"ex":"Poor factors: advanced stage, large tumour, anaplasia, 1p/16q loss. Young age is favourable.","more":"Nelson explanation:\n49.(A). Prognostic factors for risk-adapted therapy include age, stage, tumor weight,\nand loss of heterozygosity at chromosomes 1p and 16q. Histology plays a major role in\nrisk stratification of WT. Absence of anaplasia is considered a favorable histologic\nfinding.\n\nOptions:\nA is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 388 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":49,"f":false},{"id":"NEL-DERMATOLOG-050-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Although it is not common, about 15% of children with Wilms' tumor suffer relapse, most relapses occur early (within 2 yr of diagnosis). Factors associated with a favorable outcome after relapse include all the following EXCEPT","o":["low stage (1/l) at diagnosis","no prior radiotherapy","anaplastic histology","relapse to lung only","late relapse more than 12 mo from nephrectomy 378 [Continuation on source page 389]"],"k":2,"ex":"Favourable relapse factors: low stage, no prior RT, lung-only, late relapse; anaplasia is unfavourable.","more":"Nelson explanation:\n50.(C). Factors associated with a favorable outcome after relapse include low stage\n(I/l) at diagnosis, treatment with vincristine and actinomycin D only, no prior\nradiotherapy, favorable histology, relapse to lung only, and interval from nephrectomy\nto relapse 12 mo or longer.\n\nOptions:\nC is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 388 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":50,"f":false},{"id":"NEL-DERMATOLOG-051-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"A 2-mo-old male infant has a left flank mass discovered incidentally by the mother; radiological imaging reveals a left renal mass. Of the following, the MOsT likely diagnosis is","o":["nephroblastoma","neuroblastoma","mesoblastic nephroma","clear cell sarcoma","rhabdoid tumor of the kidney"],"k":2,"ex":"Congenital mesoblastic nephroma is the commonest renal tumour in neonates; Wilms is rare before 6 months.","more":"Nelson explanation:\n51.(C). Mesoblastic nephroma is the most common solid renal tumor identified in the\nneonatal period. Most of the patients are diagnosed before 3 mo of age, whereas\nWilms' tumor is rarely diagnosed before 6 mo of age. Radical nephrectomy is the\ntreatment of choice and may be sufficient by itself.\n\nOptions:\nA,B,D,E occur later.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 389 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":51,"f":false},{"id":"NEL-DERMATOLOG-053-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Renal cell carcinoma (RCC) is rare in children, accounting for <5% of all renal tumors of childhood. All the following are true regarding RCC in children EXCEPT","o":["patients may present with frank hematuria, flank pain, and/or a palpable mass","it can be asymptomatic and detected incidentally","it has a propensity to metastasize to the lungs, bone, liver, and brain","it can be associated with von hippel-lindau disease aa.","local lymph node involvement has an adverse outcome"],"k":4,"ex":"In children RCC may give haematuria, flank pain or mass and is linked to VHL; nodal spread is not poor prognostic, unlike adults.","more":"Nelson explanation:\n53.(E). Unlike the case for adult RCC, local lymph node involvement is not a poor\nprognostic indicator in pediatric RCC. Nephrectomy alone may be adequate for early-\nstage RCC.\n\nOptions:\nA–D are true.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 389 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":53,"f":false},{"id":"NEL-DERMATOLOG-058","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"Radiotherapy is an effective modality of treatment in variable pediatric solid tumors. Of the following, the LEAsT responsive tumor to radiotherapy is","o":["rhabdomyosarcoma","neuroblastoma","nephroblastoma","osteosarcoma","Ewing sarcoma"],"k":3,"ex":"Rhabdomyosarcoma, neuroblastoma, Wilms and Ewing respond to RT; osteosarcoma is radio-resistant (surgery + chemo).","more":"Nelson explanation:\n58.(D). Osteosarcoma is a radio-resistant tumor.\n\nOptions:\nA,B,C,E are radiosensitive.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 390 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":58,"f":false},{"id":"NEL-DERMATOLOG-065","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Hepatoblastoma occurs predominantly in children younger than 3 yr of age. Although etiology is unknown, there are many associated risk factors. All the following are associated risk factors for development of hepatoblastoma ExCEPT","o":["familial adenomatous polyposis","Beckwith-Wiedemann syndrome","prematurity","low birth weight","hepatitis C infection"],"k":4,"ex":"Risks: FAP, BWS, prematurity, low birth weight; hepatitis B/C cause HCC.","more":"Nelson explanation:\n65.(E). Hepatitis B or C infection is often associated with hepatocellular carcinoma.\n\nOptions:\nE is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 392 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":65,"f":false},{"id":"NEL-DERMATOLOG-066-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Hepatoblastoma is the most common neoplasm of the liver; it arises from the precursors of hepatocytes. It is of different histological classification which has a direct correlation with clinical outcome. Of the following, the histological type that predict the MOsT favorable outcome is","o":["epithelial type of pure fetal histology","epithelial type of pure embryonal histology","epithelial type of mixed histology (fetal and embryonal)","mixed type of epithelial and mesenchymal elements","undifferentiated type"],"k":0,"ex":"Pure fetal histology has the best prognosis; small-cell undifferentiated is worst.","more":"Nelson explanation:\n66.(A). The pure fetal histology subtype predicts a more favorable outcome and the\nsmall cell undifferentiated subtype is associated with normal AFP levels and predicts a\nworse outcome.\n\nOptions:\nB–E are less favourable.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 392 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":66,"f":false},{"id":"NEL-DERMATOLOG-068","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"You are examining an infant with multiple cutaneous hemangiomas; you suspect an involvement of internal organs. Of the following, the MosT common site of visceral involvement by hemangiomas is","o":["brain","heart","lung","liver","pancreas 382 [Continuation on source page 393]"],"k":3,"ex":"Multiple skin haemangiomas suggest liver involvement, so liver ultrasound/MRI is done.","more":"Nelson explanation:\n68.(D). An ultrasonographic scan or MRl of the liver should be performed if multiple\ncutaneous lesions are present.\n389\n[Source page 400]\n\nOptions:\nA,B,C,E are rare sites.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 392 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":68,"f":false},{"id":"NEL-DERMATOLOG-069-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Kasabach-Merritt syndrome is a benign vascular tumor which may be life- threatening; it is characterized by all the following EXCEPT","o":["rapidly enlarging lesion","thrombocytopenia","microangiopathic hemolytic anemia","coagulopathy","association with infantile hemangiomas"],"k":4,"ex":"KMS (consumptive coagulopathy, thrombocytopenia, MAHA) is tied to kaposiform haemangioendothelioma/tufted angioma, not infantile haemangioma.","more":"Nelson explanation:\n69.(E). All the features of Kasabach-Merritt syndrome results from platelet and red\nblood cell trapping and activation of the clotting system within the vasculature of the\nhemangioma. This syndrome is associated with kaposiform hemangioendotheliomas or\ntufted angiomas but not with infantile hemangiomas.\n\nOptions:\nA–D are features; E is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 393 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":69,"f":false},{"id":"NEL-DERMATOLOG-076-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Langerhans cell histiocytosis (LCH) has an extremely variable presentation. Single or multiple organs may be affected by the disease. Of the following, the LEAsT likely organ affected by LCH is","o":["skin","bone","middle ear","lung","lymph nodes"],"k":3,"ex":"LCH most often affects bone, then skin, ear and lymph nodes; lung is least involved (10–15%).","more":"Nelson explanation:\n76.(D). Bone is the most common site of involvement by LCH. About 50% of patients\nexperience skin involvement at some time during the course of disease. Localized or\ndisseminated lymphadenopathy is present in approximately 33% of patients. Otitis\nmedia is present in 30-40% of patients. In 10-15% of patients, pulmonary infiltrates are\nfound on radiography. The lesions may range from diffuse fibrosis and disseminated\nnodular infiltrates to diffuse cystic changes.\n\nOptions:\nA,B,C,E are more frequent.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 394 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":76,"f":false},{"id":"NEL-DERMATOLOG-077","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"In Langerhans cell histiocytosis (LCH), systemic manifestations are more likely to occur in patients with multisystem disease who are at high risk of mortality (i.e., \"risk organ\"-positive patients). All the following are risk organs in LCH ExCEPT","o":["bone","liver","spleen","lung","hematopoietic system 384"],"k":0,"ex":"Risk organs are liver, spleen and haematopoietic system; bone is a common but not 'risk' organ.","more":"Nelson explanation:\n77.(A).\n390\n\nOptions:\nB,C,E are risk organs; D (lung) is risk in older classification.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"✔ Key A consistent (lung was a risk organ in older schemes)","nlSource":"Nelson MCQs (1).md · Cancer and Benign Tumors · question page 394 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":77,"f":true},{"id":"NEL-DERMATOLOG-010","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Redundant skin over the posterior part of the neck is common in the following syndromes EXCEPT","o":["Ehlers-Danlos","Turner","Noonan","Down 528 [Continuation on source page 539]","Klippel-Feil"],"k":0,"ex":"Webbed/redundant nuchal skin occurs in Turner, Noonan, Down and Klippel-Feil; Ehlers-Danlos gives hyperextensible, not redundant, neck skin.","more":"Nelson explanation:\n10.(A). Loose folds of skin must be differentiated from a congenital defect of elastic\ntissue or collagen such as cutis laxa, Ehlers-Danlos syndrome, or pseudoxanthoma\nelasticum. Redundant skin over the posterior part of the neck is common in the Turner,\nNoonan, Down, and Klippel-Feil syndromes and monosomy 1p36; more generalized\nfolds of skin occur in infants with trisomy 18 and short-limbed dwarfism.\n\nOptions:\nB–E are all associated; A is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 538 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":10,"f":false},{"id":"NEL-DERMATOLOG-011-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Hypohidrotic ectodermal dysplasia is characterized by the following ExCEPT","o":["dry skin","sparse scalp hair","normal sexual hair growth","anodontia","delayed sexual development"],"k":4,"ex":"Hypohidrotic ectodermal dysplasia causes dry skin, sparse hair, absent teeth and no sweating, with normal puberty.","more":"Nelson explanation:\n11.(E). Sexual development is usually normal.\n\nOptions:\nA,B,D are features; E (delayed puberty) is not.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 539 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":11,"f":false},{"id":"NEL-DERMATOLOG-014-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Diagnosis","q":"A 25-day-old neonate presented with bright red, protuberant, compressible, and sharply demarcated lesion on right cheek. Of the following, the MosT likely diagnosis is","o":["strawberry hemangioma","cavernous hemangioma","superficial infantile hemangioma","deep infantile hemangioma","tufted angioma"],"k":2,"ex":"A bright red, raised, compressible, sharply demarcated lesion appearing in the first weeks is a superficial infantile haemangioma (formerly strawberry).","more":"Nelson explanation:\n14.(C). Superficial iHs are bright red, protuberant, compressible, sharply demarcated\nlesions that may occur on any area of the body. Although sometimes present at birth,\nthey more often appear in the 1st 2 mo of life and are heralded by an erythematous or\nblue mark or an area of pallor, which subsequently develops a fine telangiectatic\npattern before the growth phase.\n\nOptions:\nA (strawberry) is the old name of the same lesion; B,D are deeper/blue; E is different.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":true,"nlReason":"⚠ A and C describe the same lesion → two defensible answers; Needs Review","nlSource":"Nelson MCQs (1).md · The Skin · question page 539 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":14,"f":true},{"id":"NEL-DERMATOLOG-016-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"In the usual patient with infantile hemangiomas (IH) who has no serious complications or extensive growth resulting in tissue destruction and severe disfigurement, treatment consists of","o":["expectant observation","pulsed-dye laser therapy","topical timolol solution","oral propranolol","oral corticosteroids"],"k":0,"ex":"Most haemangiomas regress spontaneously, so uncomplicated cases are only observed with reassurance.","more":"Nelson explanation:\n16.(A). Expectant observation, because almost all lesions regress spontaneously\ntherapy is rarely indicated. Parents require repeated reassurance and support.\n\nOptions:\nB–E are for complicated lesions.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 540 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":16,"f":false},{"id":"NEL-DERMATOLOG-017","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Management","q":"In a disfiguring, life or vision threatening, or ulcerated infantile hemangiomas IH; the first-line treatment is","o":["oral corticosteroids","oral propranolol","intralesional corticosteroid injection","vincristine","interferon-α"],"k":1,"ex":"Problematic IH (disfiguring, ulcerated, vision/life threatening) is treated first with oral propranolol.","more":"Nelson explanation:\n17.(B). In a disfiguring, life- or vision-threatening, or ulcerated IH that is not responding\nto other treatment, oral propranolol is the first-line treatment in most cases. IHs\ntypically responds with growth arrest and often early signs of involution within a couple\nweeks of treatment initiation.\n\nOptions:\nA–E are older or second-line options.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 540 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":17,"f":false},{"id":"NEL-DERMATOLOG-018-3","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Evaluate for PHACEs in any patient with facial hemangioma involving significant area of face, one of the following is not a feature of PHACES","o":["posterior fossa abnormalities","arterial cerebrovascular abnormalities","coarctation of the aorta","ear abnormalities","sternal abnormalities"],"k":3,"ex":"PHACES: Posterior fossa, Haemangioma, Arterial anomalies, Coarctation/cardiac, Eye anomalies, Sternal defects.","more":"Nelson explanation:\n18.(D). PHAcEs stands for posterior fossa brain defects such as Dandy-Walker\nmalformation or cerebellar hypoplasia, large segmental facial infantile hemangioma,\narterial cerebrovascular abnormalities such as aneurysms and stroke, coarctation of the\naorta, eye abnormalities. Sternal raphe defects such as pits, scars, or supraumbilical\nraphe are infrequently observed.\n\nOptions:\nA,B,C,E are components; ear abnormalities are not (E stands for eye).","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 540 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":18,"f":false},{"id":"NEL-DERMATOLOG-020-3","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The association of spindle cell hemangiomas with nodular enchondromas in the","o":["Angiokeratoma Corporis Diffusum","Osler-Weber-Rendu Disease","Angiokeratoma of Mibelli","Kaposiform Hemangioendothelioma","Maffucci syndrome"],"k":4,"ex":"Maffucci syndrome combines multiple enchondromas with spindle-cell haemangiomas.","more":"Nelson explanation:\n20.(E).\n\nOptions:\nA–D are other vascular disorders.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 540 · answer page(s): see section manifest","nlSourceKey":"E","nlChapter":"Genetics & Dermatology","nlNumber":20,"f":false},{"id":"NEL-DERMATOLOG-025-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"The hallmark of Waardenburg type 1 is the","o":["white forelock","depigmented skin","deafness","heterochromia irides","unibrow (synophrys)"],"k":0,"ex":"Waardenburg type 1: white forelock, dystopia canthorum, deafness, heterochromia.","more":"Nelson explanation:\n25.(A). The hallmark of Waardenburg type 1 is the white forelock, which is seen in 20-\n60% of patients. Only 15% of patients have areas of depigmented skin. Deafness occurs\nin 9-37%, heterochromia irides in 20%, and unibrow (synophrys) in 17-69% of those\naffected. Dystopia canthorum (i.e., telecanthus) is seen in all patients with\nWaardenburg type 1.\n\nOptions:\nB–E occur but less often.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 541 · answer page(s): see section manifest","nlSourceKey":"A","nlChapter":"Genetics & Dermatology","nlNumber":25,"f":false},{"id":"NEL-DERMATOLOG-031-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Toxic epidermal necrolysis is characterized by the following ExCEPT","o":["widespread blister formation","skin tenderness","target lesions","sudden onset","confluent erythema"],"k":2,"ex":"TEN gives widespread blistering, tender skin, sudden onset; target lesions point to erythema multiforme.","more":"Nelson explanation:\n31.(C). TEN is defined by (1) widespread blister formation and morbilliform or confluent\nerythema, associated with skin tenderness; (2) absence of target lesions; (3) sudden\nonset and generalization within 24-48 hr; (4) histologic findings of full-thickness\nepidermal necrosis and a minimal-to-absent dermal infiltrate. These criteria categorize\nTEN as a separate entityfrom EM.\n\nOptions:\nA,B,D,E are TEN features; C is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 542 · answer page(s): see section manifest","nlSourceKey":"C","nlChapter":"Genetics & Dermatology","nlNumber":31,"f":false},{"id":"NEL-DERMATOLOG-034","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Dermatitis herpetiformis eruption is characterized by the following ExcEPT","o":["symmetric","intensely pruritic","mostly on knees and elbows","usual mucous membranes involvement","occasional hemorrhagic lesions on the palms and soles"],"k":3,"ex":"Dermatitis herpetiformis is symmetric, intensely itchy, over elbows/knees, spares mucosa and is linked to coeliac disease.","more":"Nelson explanation:\n34.(D). Mucous membranes are usually spared.\n\nOptions:\nA,B,C,E are features; D is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 543 · answer page(s): see section manifest","nlSourceKey":"D","nlChapter":"Genetics & Dermatology","nlNumber":34,"f":false},{"id":"NEL-DERMATOLOG-036-2","spec":"genetics","topic":0,"tag":"Nelson Textbook","kind":"Knowledge","q":"Diaper dermatitis can be treated with following measures ExCEPT","o":["frequent changing of the diapers","overwashing","application of a protective barrier agent","application of topical sucralfate","application of 2.5% topical hydrocortisone"],"k":1,"ex":"Nappy rash is treated with frequent changes, barrier cream (zinc oxide) and mild steroid if severe; overwashing worsens it.","more":"Nelson explanation:\n36.(B). Overwashing should be avoided because it leads to chapping and a worsening\nof the dermatitis.\n\nOptions:\nA,C,D,E help; B is the exception.","nl":true,"nlClass":"Core Accepted","nlNeedsReview":false,"nlReason":"","nlSource":"Nelson MCQs (1).md · The Skin · question page 543 · answer page(s): see section manifest","nlSourceKey":"B","nlChapter":"Genetics & Dermatology","nlNumber":36,"f":false}]);